import type { ProcessInputStepArgs, ProcessOutputStepArgs, Processor } from "@mastra/core/processors";
import type { TurnCaps } from "./caps";
import { estimateCostUsd } from "./pricing";

/**
 * RequestContext key holding the current turn's TurnBudget. Set only by the server
 * (src/chat-api.ts). Delegated sub-agents get a shallow copy of the caller's RequestContext, so
 * they see the same TurnBudget object and their model calls count toward the same turn.
 */
export const TURN_BUDGET_KEY = "nlhack.turnBudget";

export type CapReason = "cost" | "tokens";

/** Shape of the `data-turn-usage` stream part (and of the usage saved on the reply). */
export type TurnUsage = {
  costUsd: number;
  tokens: number;
  inputTokens: number;
  outputTokens: number;
  steps: number;
  capCostUsd: number;
  capTokens: number;
  capped: boolean;
  reason: CapReason | null;
  /** True on the last part of a turn. */
  final: boolean;
};

type StepUsage = { inputTokens?: number; outputTokens?: number; totalTokens?: number };

/** Usage and caps of one chat turn: every model step of the agent and of any agent it delegates to. */
export class TurnBudget {
  inputTokens = 0;
  outputTokens = 0;
  costUsd = 0;
  steps = 0;
  reason: CapReason | null = null;
  /** Called after every recorded model step (the server streams it as `data-turn-usage`). */
  onStep?: (usage: TurnUsage) => void;

  constructor(readonly caps: TurnCaps) {}

  get tokens(): number {
    return this.inputTokens + this.outputTokens;
  }

  get capped(): boolean {
    return this.reason !== null;
  }

  /** Adds one model step's usage, then marks the turn capped once either cap is exceeded. */
  record(modelId: string | undefined, usage: StepUsage | undefined): void {
    const input = safeCount(usage?.inputTokens);
    // Reasoning tokens are part of the output count; if a provider reports a larger total, the
    // difference is counted as output so nothing goes uncounted.
    const output = Math.max(safeCount(usage?.outputTokens), safeCount(usage?.totalTokens) - input);
    this.inputTokens += input;
    this.outputTokens += output;
    this.costUsd += estimateCostUsd(modelId, input, output);
    this.steps += 1;
    if (!this.reason) {
      if (this.costUsd > this.caps.costCapUsd) this.reason = "cost";
      else if (this.tokens > this.caps.tokenCap) this.reason = "tokens";
    }
    this.onStep?.(this.snapshot(false));
  }

  snapshot(final: boolean): TurnUsage {
    return {
      costUsd: round(this.costUsd),
      tokens: this.tokens,
      inputTokens: this.inputTokens,
      outputTokens: this.outputTokens,
      steps: this.steps,
      capCostUsd: this.caps.costCapUsd,
      capTokens: this.caps.tokenCap,
      capped: this.capped,
      reason: this.reason,
      final,

import { resolve } from "node:path";
import Database from "better-sqlite3";
import { dataDir } from "../data-dir";

// Which signed-in user each Neatlogs trace belongs to, in data/auth.db (own connection, same file
// as Better Auth). The Neat Bot uses it to let non-admins open only their own traces, because
// Neatlogs' trace tools return no session or user. Rows come from two places: web requests
// (src/telemetry.ts, the user is known) and a non-admin's own search results (session id
// "<userId>:<agentId>"). An existing owner is never overwritten.

let db: Database.Database | null = null;

// Open the database and create the table idempotently; safe to call repeatedly.
function ownersDb(): Database.Database {
  if (db) return db;
  const conn = new Database(resolve(dataDir(), "auth.db"));
  conn.pragma("busy_timeout = 5000");
  conn.exec(`
    CREATE TABLE IF NOT EXISTS trace_owner (
      trace_id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );
  `);
  db = conn;
  return conn;
}

// Trace ids are hex; store and compare them lowercase so case never splits one trace in two.
function normalize(traceId: string): string {
  return traceId.trim().toLowerCase();
}

/** Records the user as owner of each trace id it has no owner for yet (first owner wins). */
export function recordTraceOwners(userId: string, traceIds: Iterable<string>): void {
  const conn = ownersDb();
  const insert = conn.prepare("INSERT OR IGNORE INTO trace_owner (trace_id, user_id, created_at) VALUES (?, ?, ?)");
  const now = Date.now();
  conn.transaction(() => {
    for (const traceId of traceIds) {
      const id = normalize(traceId);
      if (id) insert.run(id, userId, now);
    }
  })();
}

/** True only when the trace is recorded as owned by this user. */
export function isTraceOwner(traceId: string, userId: string): boolean {
  const row = ownersDb().prepare("SELECT user_id FROM trace_owner WHERE trace_id = ?").get(normalize(traceId)) as
    | { user_id: string }
    | undefined;
  return row?.user_id === userId;
}
