export async function checkNeatlogsUsageOnce(traceId: string): Promise<NeatlogsUsage> {
  const key = traceId.toLowerCase();
  inFlight.add(key);
  try {
    return toNeatlogsUsage(traceId, await getTraceMetrics(traceId));
  } finally {
    inFlight.delete(key);
  }
}

